import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Tally outcomes
    cc = 0
    cd = 0
    dc = 0
    dd = 0
    opp_d = 0
    my_d = 0
    opp_c = 0
    for i in range(n):
        a, b = history[i]
        if a == 'C':
            if b == 'C':
                cc += 1
            else:
                cd += 1
        else:
            my_d += 1
            if b == 'C':
                dc += 1
            else:
                dd += 1
        if b == 'D':
            opp_d += 1
        else:
            opp_c += 1

    # Early rounds: cooperate to build trust, but be alert
    if n <= 2:
        # If opponent opened with D, retaliate immediately
        if history[-1][1] == 'D':
            return 'D'
        return 'C'

    remaining = 100 - n
    last_opp = history[-1][1]
    last_my = history[-1][0]

    # Cooperative opponent detection
    opp_rate = opp_c / n

    # Track recent opponent actions
    look = 8 if n >= 8 else n
    recent_opp_d = 0
    for i in range(n - look, n):
        if history[i][1] == 'D':
            recent_opp_d += 1

    # Detect opponent's current streak
    opp_streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak_d += 1
        else:
            break

    my_streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_streak_d += 1
        else:
            break

    # Endgame exploitation: last few rounds, defect hard
    if remaining <= 1:
        if opp_rate > 0.9 and opp_d <= 2:
            return 'C'
        return 'D'

    if remaining <= 4:
        if opp_rate > 0.85 and opp_d <= 3:
            return 'C'
        return 'D'

    if remaining <= 10:
        # Opponent very cooperative - defect to exploit
        if opp_rate > 0.85:
            if last_opp == 'C' and rng.random() < 0.7:
                return 'D'
            return 'C'
        # Otherwise defect
        if opp_rate > 0.5:
            return 'D' if rng.random() < 0.6 else 'C'
        return 'D'

    # Detecting always-cooperator: exploit it
    if opp_d == 0 and n >= 8:
        # Never defected - exploit heavily but occasionally maintain
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Detecting nearly always-defector: defect back
    if opp_rate < 0.1 and n >= 6:
        if rng.random() < 0.03:
            return 'C'
        return 'D'

    # Opponent just defected
    if last_opp == 'D':
        # If opponent has been very cooperative historically, treat as noise/mistake
        if opp_rate > 0.85 and recent_opp_d <= 2 and n < 90:
            # Forgive once; retaliate if they repeat
            if opp_streak_d >= 2:
                return 'D'
            return 'C'
        # If we're locked in mutual defection, occasionally try to reset
        if last_my == 'D' and my_streak_d >= 3:
            if rng.random() < 0.2:
                return 'C'
            return 'D'
        # Otherwise retaliate
        return 'D'

    # Opponent just cooperated
    if last_opp == 'C':
        # If we just defected and opponent continued cooperating, exploit more
        if last_my == 'D':
            if opp_rate > 0.7 and n < 90:
                if rng.random() < 0.6:
                    return 'D'
                return 'C'
            return 'C'
        # If opponent is moderately defective, be cautious
        if opp_rate < 0.4 and n >= 10:
            # Probe occasionally
            if rng.random() < 0.25:
                return 'D'
            return 'C'
        # Opponent is reasonably cooperative
        if opp_rate > 0.7 and n < 90 and rng.random() < 0.05:
            return 'D'
        return 'C'

    return 'C'
